examples.setupTemplate:
struct MetricProps: Decodable, Sendable {
    let label: String
    let value: String
    let change: String?
}

var registry: MonarchAiUiRegistry {
    var registry = MonarchAiUiRegistry()
    registry.register({{component}}, props: MetricProps.self) { props, _ in
        MonarchCard {
            Text(props.label).monarchTextStyle(.subheading)
            Text(props.value).monarchTextStyle(.title)
            if let change = props.change {
                MonarchBadge(change, tone: .success)
            }
        }
    }
    return registry
}

